#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
JS="$GSZ/public/js/app.js"; CSS="$GSZ/public/css/app.css"
TOP="$GSZ/views/partials/store_top.ejs"; BOT="$GSZ/views/partials/store_bottom.ejs"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step173: marquee icons + calmer/restyled order toss + cache bump"
for F in "$JS" "$CSS" "$TOP" "$BOT"; do cp "$F" "$F.bak-step173-$TS"; done
echo "    backups: *.bak-step173-$TS"
restore(){ echo "!! restoring"; for F in "$JS" "$CSS" "$TOP" "$BOT"; do cp "$F.bak-step173-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
PATCHER=$(mktemp /tmp/patch_step173.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$JS" && echo "    app.js ok"
for V in "$TOP" "$BOT"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$V','utf8'),{filename:'$V'});console.log('    ejs ok: $V')"; done
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$PATCHER"; trap - ERR
echo ""
echo "==> step173 OK  Marquee items now each have their own icon; the 'someone just ordered' popup is throttled to ~once per 15 min (no longer restarts every page) and restyled. Hard-refresh once (Ctrl+Shift+R)."
